// The fixtures in testdata/fixtures are generated by this file, so every
// byte is reviewable here. They are built as raw opcodes/bytes: no Python
// and no pickle library is involved, and nothing is ever executed.
//
//	go test ./internal/models -run TestFixturesUpToDate -update
var update = flag.Bool("update", false, "regenerate testdata fixtures and golden files")

const fixtureDir = "testdata/fixtures"

// ---- pickle opcode builder ----

type pk struct{ bytes.Buffer }

func newPk(proto byte) *pk {
	p := &pk{}
	if proto >= 2 {
		p.WriteByte(0x80)
		p.WriteByte(proto)
	}
	return p
}
func (p *pk) op(b ...byte) *pk { p.Write(b); return p }
func (p *pk) global(mod, name string) *pk {
	p.WriteString("c" + mod + "\n" + name + "\n")
	return p
}
func (p *pk) uni(s string) *pk { // BINUNICODE
	p.WriteByte('X')
	binary.Write(p, binary.LittleEndian, uint32(len(s)))
	p.WriteString(s)
	return p
}
func (p *pk) short(s string) *pk { // SHORT_BINUNICODE
	p.WriteByte(0x8c)
	p.WriteByte(byte(len(s)))
	p.WriteString(s)
	return p
}
func (p *pk) stop() []byte { p.WriteByte('.'); return p.Bytes() }

// torchStateDict is what torch.save({'weight': tensor}) looks like
// (protocol 2): only allowlisted rebuild imports.
func torchStateDict() []byte {
	p := newPk(2)
	p.global("collections", "OrderedDict").op(')', 'R', 'q', 0)
	p.op('(').uni("weight")
	p.global("torch._utils", "_rebuild_tensor_v2")
	p.op('(', '(').uni("storage").global("torch", "FloatStorage").uni("0").uni("cpu").op('K', 4, 't', 'Q')
	p.op('K', 0, 'K', 4, 0x85, 'K', 1, 0x85, 0x89)
	p.global("collections", "OrderedDict").op(')', 'R')
	p.op('t', 'R', 'u')
	return p.stop()
}

// printPayload calls builtins.print: the harmless stand-in for code
// execution that the demo app also uses (CLAUDE.md demo-safety rule).
func printPayload() []byte {
	p := newPk(4)
	p.short("builtins").op(0x94).short("print").op(0x94, 0x93, 0x94)
	p.short("gapproof-demo: code execution would happen here").op(0x94, 0x85, 0x94, 'R', 0x94)
	return p.stop()
}

// py2RangeObjArr has the shape of numpy's py2-objarr.npy test fixture: a
// protocol 2 object array holding the xrange type itself (GLOBAL
// __builtin__ xrange, not called), plus a called range(3). D-035: neither
// is a finding.
func py2RangeObjArr() []byte {
	p := newPk(2)
	p.op(']').global("__builtin__", "xrange").op('a')
	p.global("builtins", "range").op('K', 3, 0x85, 'R', 'a')
	return p.stop()
}

// rangeGetattrChain tries to launder getattr behind an allowlisted
// constructor: getattr(range(3), "count"), with getattr reached through
// memoised STACK_GLOBAL operands. range is fine; getattr stays critical.
func rangeGetattrChain() []byte {
	p := newPk(4)
	p.short("builtins").op(0x94).short("getattr").op(0x94, 0x93, 0x94)
	p.short("builtins").op(0x94).short("range").op(0x94, 0x93, 'K', 3, 0x85, 'R')
	p.short("count").op(0x86, 'R')
	return p.stop()
}

// osSystemViaMemo reaches os.system through STACK_GLOBAL with operands
// routed through the memo, which defeats scanners that only look at the
// preceding string opcodes. Bytes only: never loaded.
func osSystemViaMemo() []byte {
	p := newPk(4)
	p.short("os").op(0x94).short("system").op(0x94)
	p.op('0', '0')             // POP both strings off the stack
	p.op('h', 0, 'h', 1, 0x93) // BINGET 0, BINGET 1, STACK_GLOBAL
	p.short("echo gapproof-fixture").op(0x85, 'R')
	return p.stop()
}

func unresolvedGlobal() []byte {
	return newPk(4).short("os").op(']', 0x93).stop() // name operand isn't a string
}

func extRegistry() []byte { return newPk(2).op(0x82, 1).stop() }

func legacyTorch() []byte {
	var b bytes.Buffer
	b.Write(legacyTorchMagic)
	b.Write(newPk(2).op('M', 0xe9, 0x03).stop())      // protocol version 1001
	b.Write(newPk(2).op('}').stop())                  // sys_info
	b.Write(torchStateDict())                         // the object
	b.Write(newPk(2).op(']').uni("0").op('a').stop()) // storage keys
	b.Write([]byte{0x80, 0x99, 'r', 'a', 'w'})        // raw storage bytes: must not be walked
	return b.Bytes()
}

// zipBombPickle declares a 64 MiB string of zeros: tiny compressed, huge expanded.
func zipBombPickle() []byte {
	var b bytes.Buffer
	b.Write([]byte{0x80, 0x02, 'X'})
	binary.Write(&b, binary.LittleEndian, uint32(64<<20))
	b.Write(make([]byte, 64<<20))
	b.WriteByte('.')
	return b.Bytes()
}

// ---- containers ----

type member struct {
	name string
	data []byte
}

func zipOf(t *testing.T, ms ...member) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	for _, m := range ms {
		w, err := zw.CreateHeader(&zip.FileHeader{Name: m.name, Method: zip.Deflate})
		if err != nil {
			t.Fatal(err)
		}
		w.Write(m.data)
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func torchZip(t *testing.T, dataPkl []byte, extra ...member) []byte {
	ms := []member{{"archive/data.pkl", dataPkl}, {"archive/data/0", make([]byte, 16)}, {"archive/version", []byte("3\n")}}
	return zipOf(t, append(ms, extra...)...)
}

func safetensors(header string, data []byte) []byte {
	for (8+len(header))%8 != 0 {
		header += " "
	}
	var b bytes.Buffer
	binary.Write(&b, binary.LittleEndian, uint64(len(header)))
	b.WriteString(header)
	b.Write(data)
	return b.Bytes()
}

const stHeader = `{"__metadata__":{"format":"pt"},"weight":{"dtype":"F32","shape":[2,2],"data_offsets":[0,16]},"bias":{"dtype":"BF16","shape":[2],"data_offsets":[16,20]}}`

// ---- GGUF ----

type gg struct{ bytes.Buffer }

func (g *gg) u32(v uint32) *gg { binary.Write(g, binary.LittleEndian, v); return g }
func (g *gg) u64(v uint64) *gg { binary.Write(g, binary.LittleEndian, v); return g }
func (g *gg) str(s string) *gg { g.u64(uint64(len(s))); g.WriteString(s); return g }
func (g *gg) kvStr(k, v string) *gg {
	return g.str(k).u32(ggufString).str(v)
}

func ggufFile(chatTemplate string) []byte {
	g := &gg{}
	g.WriteString("GGUF")
	g.u32(3).u64(1).u64(6)
	g.kvStr("general.architecture", "llama")
	g.kvStr("general.name", "tiny-test")
	g.kvStr("general.license", "apache-2.0")
	g.str("tokenizer.ggml.tokens").u32(ggufArray).u32(ggufString).u64(2).str("a").str("b")
	g.str("llama.context_length").u32(ggufU32).u32(2048)
	g.kvStr("tokenizer.chat_template", chatTemplate)
	g.str("blk.0.attn.weight").u32(2).u64(4).u64(8).u32(0).u64(0) // one 4x8 tensor
	return g.Bytes()
}

// ---- ONNX (protobuf) ----

func pbTag(b *bytes.Buffer, num, wire int) { pbUvarint(b, uint64(num<<3|wire)) }
func pbUvarint(b *bytes.Buffer, v uint64) {
	for v >= 0x80 {
		b.WriteByte(byte(v) | 0x80)
		v >>= 7
	}
	b.WriteByte(byte(v))
}
func pbLen(num int, payload []byte) []byte {
	var b bytes.Buffer
	pbTag(&b, num, 2)
	pbUvarint(&b, uint64(len(payload)))
	b.Write(payload)
	return b.Bytes()
}
func pbVar(num int, v uint64) []byte {
	var b bytes.Buffer
	pbTag(&b, num, 0)
	pbUvarint(&b, v)
	return b.Bytes()
}
func cat(bs ...[]byte) []byte { return bytes.Join(bs, nil) }

func onnxExternalTensor(name, location string) []byte {
	entry := cat(pbLen(1, []byte("location")), pbLen(2, []byte(location)))
	return cat(pbVar(1, 2), pbVar(2, 1), pbLen(8, []byte(name)), pbLen(13, entry), pbVar(14, 1))
}

func onnxModel(initializers [][]byte, subgraphTensors [][]byte) []byte {
	var graph [][]byte
	graph = append(graph, pbLen(2, []byte("g")))
	for _, t := range initializers {
		graph = append(graph, pbLen(5, t))
	}
	if len(subgraphTensors) > 0 {
		var sub [][]byte
		for _, t := range subgraphTensors {
			sub = append(sub, pbLen(5, t))
		}
		attr := cat(pbLen(1, []byte("then_branch")), pbLen(6, cat(sub...)))
		node := cat(pbLen(4, []byte("If")), pbLen(5, attr))
		graph = append(graph, pbLen(1, node))
	}
	return cat(pbVar(1, 8), pbLen(7, cat(graph...)))
}

// ---- NumPy / Keras ----

func npyObjectFile(payload []byte) []byte {
	hdr := "{'descr': '|O', 'fortran_order': False, 'shape': (1,), }"
	for (10+len(hdr)+1)%64 != 0 {
		hdr += " "
	}
	hdr += "\n"
	var b bytes.Buffer
	b.WriteString("\x93NUMPY\x01\x00")
	binary.Write(&b, binary.LittleEndian, uint16(len(hdr)))
	b.WriteString(hdr)
	b.Write(payload)
	return b.Bytes()
}

// fixtures returns every fixture file, relative to fixtureDir.
func fixtures(t *testing.T) map[string][]byte {
	bomb := zipBombPickle()
	return map[string][]byte{
		"pickle/benign_state_dict.pt":       torchZip(t, torchStateDict()),
		"pickle/print_payload.pt":           torchZip(t, printPayload()),
		"pickle/print_payload.pkl":          printPayload(),
		"pickle/stack_global_os_system.pkl": osSystemViaMemo(),
		"pickle/unresolved_global.pkl":      unresolvedGlobal(),
		"pickle/ext_registry.pkl":           extRegistry(),
		"pickle/legacy_torch.pt":            legacyTorch(),
		"pickle/truncated.pkl":              printPayload()[:12],
		"pickle/zip_bomb.pt":                torchZip(t, bomb),
		"pickle/duplicate_member.pt":        zipOf(t, member{"archive/data.pkl", torchStateDict()}, member{"archive/data.pkl", printPayload()}),
		"pickle/torchscript.pt": zipOf(t,
			member{"m/data.pkl", torchStateDict()},
			member{"m/constants.pkl", newPk(2).op(')').stop()},
			member{"m/code/__torch__/model.py", []byte("def forward(self, x):\n    return x\n")}),
		"pickle/model.joblib": {0x78, 0x9c, 0x01, 0x02, 0x03},

		"safetensors/hf_ok/model.safetensors": safetensors(stHeader, make([]byte, 20)),
		"safetensors/hf_ok/config.json":       []byte(`{"architectures":["LlamaForCausalLM"],"model_type":"llama"}`),
		"safetensors/hf_ok/README.md":         []byte("---\nlicense: apache-2.0\nlanguage: en\n---\n# tiny\n"),
		"safetensors/truncated.safetensors":   safetensors(stHeader, make([]byte, 6)),

		"hf/remote_code/config.json":           []byte(`{"model_type":"custom","auto_map":{"AutoModel":"modeling_custom.CustomModel"}}`),
		"hf/remote_code/tokenizer_config.json": []byte(`{"tokenizer_class":"X","chat_template":"{{ ''.__class__.__mro__[1].__subclasses__() }}"}`),
		"hf/not_a_model/config.json":           []byte(`{"name":"web-app","port":8080}`),

		"gguf/tiny.gguf": ggufFile("{% for m in messages %}{{ m['content'] }}{% endfor %}"),
		"gguf/ssti.gguf": ggufFile("{{ cycler.__init__.__globals__.os.popen('id').read() }}"),
		"gguf/v1.gguf":   []byte("GGUF\x01\x00\x00\x00"),

		"onnx/escape.onnx": onnxModel(
			[][]byte{onnxExternalTensor("w", "weights.data")},
			[][]byte{onnxExternalTensor("w2", "../../../etc/shadow")}),
		"onnx/weights.data": make([]byte, 16),
		"onnx/missing.onnx": onnxModel([][]byte{onnxExternalTensor("w", "not_shipped.data")}, nil),
		"onnx/garbage.onnx": {0x0f, 0xff, 0xff},

		"numpy/object.npy":               npyObjectFile(printPayload()),
		"numpy/py2_range_objarr.npy":     npyObjectFile(py2RangeObjArr()),
		"pickle/range_getattr_chain.pkl": rangeGetattrChain(),
		"keras/lambda.keras": zipOf(t, member{"config.json", []byte(`{"module":"keras","class_name":"Sequential","config":{"layers":[{"module":"keras.layers","class_name":"Lambda","config":{"function":{"class_name":"__lambda__","config":{"code":"4wEAAAAA"}}}}]}}`)},
			member{"metadata.json", []byte(`{"keras_version":"3.6.0"}`)}),
		"keras/module_bypass.keras": zipOf(t, member{"config.json", []byte(`{"module":"keras.layers","class_name":"Dense","config":{"activation":{"module":"builtins","class_name":"function","config":"exec"}}}`)}),
		"keras/lambda.h5":           cat([]byte("\x89HDF\r\n\x1a\n"), make([]byte, 2000), []byte(`{"class_name": "Lambda", "config": {}}`), make([]byte, 100)),

		"other/firmware.bin": bytes.Repeat([]byte{0xde, 0xad, 0xbe, 0xef}, 64),
	}
}

func TestFixturesUpToDate(t *testing.T) {
	want := fixtures(t)
	if *update {
		os.RemoveAll(fixtureDir)
		for name, data := range want {
			p := filepath.Join(fixtureDir, name)
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(p, data, 0o644); err != nil {
				t.Fatal(err)
			}
		}
	}
	var onDisk []string
	filepath.WalkDir(fixtureDir, func(p string, d os.DirEntry, err error) error {
		if err == nil && !d.IsDir() {
			rel, _ := filepath.Rel(fixtureDir, p)
			onDisk = append(onDisk, filepath.ToSlash(rel))
		}
		return nil
	})
	var names []string
	for n := range want {
		names = append(names, n)
	}
	slices.Sort(names)
	slices.Sort(onDisk)
	if !slices.Equal(names, onDisk) {
		t.Fatalf("fixture set differs from generator; run with -update\n generator: %v\n on disk:   %v", names, onDisk)
	}
	for _, n := range names {
		got, _ := os.ReadFile(filepath.Join(fixtureDir, n))
		if !bytes.Equal(got, want[n]) && !sameZip(got, want[n]) {
			t.Errorf("%s differs from its generator; run with -update", n)
		}
	}
	if strings.Contains(string(printPayload()), "system") {
		t.Fatal("the print payload must stay harmless")
	}
}

// sameZip reports whether a and b are zips with the same members (name,
// method, decompressed content) in the same order. compress/flate's output
// differs between Go releases, and CI runs the minimum Go in go.mod, so zip
// fixtures are compared by content; the scanners only see decompressed bytes.
func sameZip(a, b []byte) bool {
	za, err1 := zip.NewReader(bytes.NewReader(a), int64(len(a)))
	zb, err2 := zip.NewReader(bytes.NewReader(b), int64(len(b)))
	if err1 != nil || err2 != nil || len(za.File) != len(zb.File) {
		return false
	}
	for i, fa := range za.File {
		fb := zb.File[i]
		if fa.Name != fb.Name || fa.Method != fb.Method {
			return false
		}
		da, db := readMember(fa), readMember(fb)
		if da == nil || db == nil || !bytes.Equal(da, db) {
			return false
		}
	}
	return true
}

func readMember(f *zip.File) []byte {
	r, err := f.Open()
	if err != nil {
		return nil
	}
	defer r.Close()
	b, err := io.ReadAll(io.LimitReader(r, 64<<20))
	if err != nil {
		return nil
	}
	return b
}
